package ai.neargo.shop.scenario;
import ai.neargo.shop.auth.*;import ai.neargo.shop.member.service.*;import ai.neargo.shop.member.dto.MemberCodeScope;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.context.WebApplicationContext;import org.springframework.security.test.web.servlet.setup.SecurityMockMvcConfigurers;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import org.springframework.http.MediaType;import tools.jackson.databind.ObjectMapper;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:brand-member-http;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","shop.person.phone-key=YWktc2hvcC10ZXN0LWtleS0zMmJ5dGVzLSEhYWFhYSE=","shop.member-code.enabled=true","shop.pay.stored-value.enabled=true","shop.management.signing-key=member-brand-http-secret-at-least-thirty-two-chars","shop.pay.entitlement.cursor-key=member-brand-http-secret-at-least-thirty-two-chars"}) @ActiveProfiles("test")
class MemberBrandHttpFlowTest {
 @Autowired JdbcTemplate jdbc;@Autowired WebApplicationContext web;@Autowired ObjectMapper json;@Autowired TokenStores tokens;@Autowired MemberCodeResolveService references;@Autowired ai.neargo.shop.common.OtpStore otp;
 @Test void enrollViaExistingMemberEntrySearchAcrossEntitiesAndKeepWalletStoreBound() throws Exception {
  var mvc=MockMvcBuilders.webAppContextSetup(web).apply(SecurityMockMvcConfigurers.springSecurity()).build();String suffix=UUID.randomUUID().toString().replace("-","");String e1="E1"+suffix,e2="E2"+suffix,s1="S1"+suffix,s2="S2"+suffix,s3="S3"+suffix,a1="A1"+suffix,a2="A2"+suffix,m="M"+suffix,b="B"+suffix;
  for(String e:List.of(e1,e2))jdbc.update("INSERT INTO mch_entity(entity_no,name,status,market,tenant_no,created_at,updated_at) VALUES (?,'会员主体','ACTIVE','CN','MAIN',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",e);
  for(String s:List.of(s1,s2,s3))jdbc.update("INSERT INTO mch_store(store_no,entity_no,name,status,tenant_no,created_at,updated_at) VALUES (?,?,'会员门店','ACTIVE','MAIN',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",s,s.equals(s1)?e1:e2);
  for(String a:List.of(a1,a2))jdbc.update("INSERT INTO mch_account(mch_account_no,entity_no,is_owner,is_primary,status,tenant_no,created_at,updated_at) VALUES (?,?,1,1,'ACTIVE','MAIN',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",a,a.equals(a1)?e1:e2);
  jdbc.update("INSERT INTO mch_management_space(management_no,name,owner_actor_no,status,bootstrap_source_account_no,bootstrap_key,bootstrap_hash,tenant_no,created_at,updated_at,created_by,updated_by) VALUES (?,'会员测试',?,'ACTIVE',?,'boot','hash','MAIN',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,'TEST','TEST')",m,"MCH:"+a1,a1);
  jdbc.update("INSERT INTO mch_brand(brand_no,management_no,name,name_key,status,scope_revision,create_key,create_hash,tenant_no,created_at,updated_at,created_by,updated_by) VALUES (?,?,'共享品牌','共享品牌','ACTIVE',1,'create','hash','MAIN',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,'TEST','TEST')",b,m);
  for(String s:List.of(s1,s2))jdbc.update("INSERT INTO mch_brand_store_binding(binding_no,brand_no,store_no,status,effective_from,scope_revision,change_no,tenant_no,created_at,updated_at,created_by,updated_by) VALUES (?,?,?,'ACTIVE',CURRENT_TIMESTAMP,1,?,'MAIN',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,'TEST','TEST')","BIND"+s,b,s,"C"+s);
  String t1=tokens.of(Realm.MERCHANT).issue(TokenStore.SessionData.of(LoginUser.merchant(a1,"甲"))),t2=tokens.of(Realm.MERCHANT).issue(TokenStore.SessionData.of(LoginUser.merchant(a2,"乙")));String phone="139"+String.format("%08d",Math.abs(new Random().nextInt(100000000)));
  var created=mvc.perform(post("/biz/members").header("Authorization","Bearer "+t1).header("X-Store-No",s1).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("phone",phone,"remark","仅甲店私有","storeNo",s1)))).andReturn().getResponse();assertThat(json.readTree(created.getContentAsString()).path("code").asInt()).as(created.getContentAsString()).isZero();
  var response=mvc.perform(get("/biz/stores/"+s2+"/stored-value/customer-candidates").param("keyword",phone).header("Authorization","Bearer "+t2).header("X-Store-No",s2)).andReturn().getResponse();var page=json.readTree(response.getContentAsString());assertThat(page.path("code").asInt()).as(response.getContentAsString()).isZero();assertThat(page.path("data").path("items").size()).as(response.getContentAsString()).isEqualTo(1);var candidate=page.path("data").path("items").get(0);String member=candidate.path("memberNo").asString();assertThat(candidate.path("displayName").asString()).doesNotContain("私有");assertThat(candidate.path("sourceStoreNo").asString()).isEqualTo(s1);assertThat(candidate.path("account").isNull()).isTrue();
  var selected=mvc.perform(post("/biz/stores/"+s2+"/stored-value/customer-selections").header("Authorization","Bearer "+t2).header("X-Store-No",s2).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("source",Map.of("type","MEMBER","memberNo",member))))).andReturn().getResponse();var selection=json.readTree(selected.getContentAsString());assertThat(selection.path("code").asInt()).as(selected.getContentAsString()).isZero();String ref=selection.path("data").path("selection").path("customerRef").asString();assertThat(references.requireReference(new MemberCodeScope("MAIN",e2,s2,a2),ref).customerNo()).isNotBlank();
  var other=mvc.perform(get("/biz/stores/"+s3+"/stored-value/customer-candidates").param("keyword",phone).header("Authorization","Bearer "+t2).header("X-Store-No",s3)).andReturn().getResponse();assertThat(json.readTree(other.getContentAsString()).path("data").path("items").size()).isZero();
  String consumerToken=ai.neargo.shop.support.TestLogin.consumer(mvc,json,otp,phone);String consumer=tokens.of(Realm.CONSUMER).get(consumerToken).orElseThrow().user().userNo();
  assertThat(jdbc.queryForObject("SELECT status FROM mbr_scope_member WHERE scope_member_no=?",String.class,member)).isEqualTo("ACTIVE");
  var memberCode=references.issue("MAIN",consumer);
  var byCode=mvc.perform(post("/biz/stores/"+s2+"/stored-value/customer-selections").header("Authorization","Bearer "+t2).header("X-Store-No",s2).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("source",Map.of("type","MEMBER_CODE","code",memberCode.memberCode()))))).andReturn().getResponse();
  var identified=json.readTree(byCode.getContentAsString());assertThat(identified.path("code").asInt()).as(byCode.getContentAsString()).isZero();assertThat(identified.path("data").path("selection").path("memberNo").asString()).isEqualTo(member);assertThat(identified.path("data").path("selection").path("account").isNull()).isTrue();
  assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM sv_account",Long.class)).isZero();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM sv_recharge",Long.class)).isZero();
  jdbc.update("UPDATE mch_brand SET scope_revision=2 WHERE brand_no=?",b);assertThatThrownBy(()->references.requireReference(new MemberCodeScope("MAIN",e2,s2,a2),ref)).isInstanceOf(ai.neargo.shop.common.BizException.class);
 }
}
